 @Test void trackingMatrixLotLifecycleAndExpiryAreEnforced()throws Exception{grantTrace();db.update("UPDATE catalog_product_variants SET tracking_mode='LOT',expiration_required=true WHERE id=?",V);mvc.perform(post("/api/v1/inventory/lots").with(token()).contentType("application/json").content("{\"variantId\":\""+V+"\",\"lotNumber\":\" lot-a \"}")).andExpect(status().isBadRequest());UUID lot=UUID.randomUUID();db.update("INSERT INTO inventory_lots(id,tenant_id,variant_id,lot_number,normalized_lot_number,expires_on,status,created_at,updated_at,version)VALUES (?,?,?,?,?,current_date-1,'ACTIVE',now(),now(),0)",lot,T,V,"Lot-A","LOT-A");postTrace("lot-open","1",lot,null,L).andExpect(status().isOk());mvc.perform(get("/api/v1/inventory/lots/"+lot).with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.expiryState").value("EXPIRED"));mvc.perform(post("/api/v1/inventory/lots/"+lot+"/archive").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("LOT_HAS_ON_HAND"));postTrace("lot-close","-1",lot,null,L).andExpect(status().isOk());mvc.perform(post("/api/v1/inventory/lots/"+lot+"/archive").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isOk());}
 @Test void serialGlobalPresenceIsProtectedUnderConcurrency()throws Exception{grantTrace();db.update("UPDATE catalog_product_variants SET tracking_mode='SERIAL' WHERE id=?",V);UUID serial=UUID.randomUUID(),other=UUID.randomUUID();db.update("INSERT INTO inventory_serials(id,tenant_id,variant_id,serial_number,normalized_serial_number,status,created_at,updated_at,version)VALUES (?,?,?,?,?,'ACTIVE',now(),now(),0)",serial,T,V,"SN-1","SN-1");db.update("INSERT INTO warehouse_locations(id,tenant_id,warehouse_id,zone_id,code,normalized_code,type,status,scan_code,normalized_scan_code,created_at,updated_at,version)VALUES (?,?,?,?,?,?,'BIN','ACTIVE',?,?,now(),now(),0)",other,T,W,Z,"L2","L2","SCAN2","SCAN2");ExecutorService pool=Executors.newFixedThreadPool(12);try{CountDownLatch ready=new CountDownLatch(12),go=new CountDownLatch(1);List<Future<Integer>>calls=new ArrayList<>();for(int i=0;i<12;i++){int n=i;calls.add(pool.submit(()->{ready.countDown();go.await();return postTrace("serial-"+n,"1",null,serial,n%2==0?L:other).andReturn().getResponse().getStatus();}));}ready.await();go.countDown();int ok=0,conflict=0;for(var f:calls){int s=f.get();if(s==200)ok++;else if(s==400)conflict++;}assertEquals(1,ok);assertEquals(11,conflict);assertEquals(1,db.queryForObject("SELECT sum(on_hand_quantity) FROM inventory_balances WHERE serial_id=?",Integer.class,serial));assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_ledger_entries WHERE serial_id=?",Integer.class,serial));}finally{pool.shutdownNow();}}
 @Test void noneAndSerialTrackingRejectMismatchedIdentifiers()throws Exception{grantTrace();UUID lot=UUID.randomUUID(),serial=UUID.randomUUID();mvc.perform(post("/api/v1/inventory/adjustments").with(token()).header("Idempotency-Key","none-lot").contentType("application/json").content(traceBody("1",lot,null,L))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("LOT_NOT_ALLOWED"));db.update("UPDATE catalog_product_variants SET tracking_mode='SERIAL' WHERE id=?",V);postTrace("serial-missing","1",null,null,L).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("SERIAL_REQUIRED"));db.update("INSERT INTO inventory_serials(id,tenant_id,variant_id,serial_number,normalized_serial_number,status,created_at,updated_at,version)VALUES (?,?,?,?,?,'ACTIVE',now(),now(),0)",serial,T,V,"SN","SN");postTrace("serial-two","2",null,serial,L).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_SERIAL_QUANTITY"));}
 @Test void reservationDoesNotMovePhysicalStockAndReleaseIsIdempotent()throws Exception{grantReservations();postAdjustment("stock","10").andExpect(status().isOk());int ledger=db.queryForObject("SELECT count(*) FROM inventory_ledger_entries",Integer.class);postReservation("hold","4",null,null,L).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("ACTIVE"));UUID id=db.queryForObject("SELECT id FROM inventory_reservations WHERE idempotency_key='hold'",UUID.class);mvc.perform(get("/api/v1/inventory/balances").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$[0].onHand").value(10.0)).andExpect(jsonPath("$[0].reserved").value(4.0)).andExpect(jsonPath("$[0].available").value(6.0));mvc.perform(get("/api/v1/inventory/availability?variantId="+V).with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.availableToPromise").value(6.0));mvc.perform(post("/api/v1/inventory/reservations/"+id+"/release").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("RELEASED"));mvc.perform(post("/api/v1/inventory/reservations/"+id+"/release").with(token())).andExpect(status().isOk());assertEquals(ledger,db.queryForObject("SELECT count(*) FROM inventory_ledger_entries",Integer.class));assertEquals(0,db.queryForObject("SELECT reserved_quantity FROM inventory_balances",Integer.class));}
 @Test void reservationIdempotencyBoundsAndReservedAdjustmentAreEnforced()throws Exception{grantReservations();postAdjustment("stock","5").andExpect(status().isOk());postReservation("same-hold","3",null,null,L).andExpect(status().isOk());postReservation("same-hold","3",null,null,L).andExpect(status().isOk());assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_reservations",Integer.class));postReservation("same-hold","2",null,null,L).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("RESERVATION_IDEMPOTENCY_KEY_REUSED"));postReservation("too-much","3",null,null,L).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("INSUFFICIENT_AVAILABLE_INVENTORY"));postAdjustment("reserved-debit","-3").andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("INVENTORY_QUANTITY_RESERVED"));mvc.perform(get("/api/v1/inventory/reservations?size=101").with(token())).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/inventory/reservations?sort=tenantId").with(token())).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/inventory/reservation-candidates?variantId="+V).with(token())).andExpect(status().isOk()).andExpect(jsonPath("$[0].available").value(2.0));mvc.perform(get("/api/v1/inventory/reservation-reconciliation").with(token())).andExpect(status().isOk()).andExpect(content().json("[]"));}
 @Test void twentyCompetingReservationsCannotOverbook()throws Exception{grantReservations();postAdjustment("stock","10").andExpect(status().isOk());ExecutorService pool=Executors.newFixedThreadPool(20);try{CountDownLatch ready=new CountDownLatch(20),go=new CountDownLatch(1);List<Future<Integer>>calls=new ArrayList<>();for(int i=0;i<20;i++){int n=i;calls.add(pool.submit(()->{ready.countDown();go.await();return postReservation("hold-"+n,"1",null,null,L).andReturn().getResponse().getStatus();}));}ready.await();go.countDown();int ok=0,conflict=0;for(var f:calls){int s=f.get();if(s==200)ok++;else if(s==409)conflict++;}assertEquals(10,ok);assertEquals(10,conflict);assertEquals(10,db.queryForObject("SELECT reserved_quantity FROM inventory_balances",Integer.class));assertEquals(10,db.queryForObject("SELECT count(*) FROM inventory_reservations WHERE status='ACTIVE'",Integer.class));}finally{pool.shutdownNow();}}
 @Test void reservationAuthorizationAndTenantIsolationAreEnforced()throws Exception{postAdjustment("stock","1").andExpect(status().isOk());mvc.perform(get("/api/v1/inventory/reservations")).andExpect(status().isUnauthorized());postReservation("denied","1",null,null,L).andExpect(status().isForbidden());grantReservations();String json=postReservation("visible","1",null,null,L).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String id=json.replaceAll(".*\"id\":\"([^\"]+)\".*","$1");UUID other=UUID.randomUUID();mvc.perform(get("/api/v1/inventory/reservations/"+id).with(jwt().jwt(j->j.subject("admin").claim("tenant_id",other.toString())))).andExpect(status().isForbidden());mvc.perform(get("/api/v1/inventory/availability?variantId="+V).with(jwt().jwt(j->j.subject("admin").claim("tenant_id",other.toString())))).andExpect(status().isForbidden());}
 @Test void concurrentReleaseDecrementsProjectionOnce()throws Exception{grantReservations();postAdjustment("release-stock","1").andExpect(status().isOk());postReservation("release-hold","1",null,null,L).andExpect(status().isOk());UUID id=db.queryForObject("SELECT id FROM inventory_reservations WHERE idempotency_key='release-hold'",UUID.class);ExecutorService pool=Executors.newFixedThreadPool(10);try{List<Future<Integer>>calls=new ArrayList<>();for(int i=0;i<10;i++)calls.add(pool.submit(()->mvc.perform(post("/api/v1/inventory/reservations/"+id+"/release").with(token())).andReturn().getResponse().getStatus()));for(var call:calls)assertEquals(200,call.get());assertEquals(0,db.queryForObject("SELECT reserved_quantity FROM inventory_balances",Integer.class));assertEquals("RELEASED",db.queryForObject("SELECT status FROM inventory_reservations WHERE id=?",String.class,id));}finally{pool.shutdownNow();}}
 @Test void adjustmentReservationRacePreservesInvariant()throws Exception{grantReservations();postAdjustment("race-stock","10").andExpect(status().isOk());ExecutorService pool=Executors.newFixedThreadPool(2);try{CountDownLatch go=new CountDownLatch(1);Future<Integer>reserve=pool.submit(()->{go.await();return postReservation("race-hold","8",null,null,L).andReturn().getResponse().getStatus();});Future<Integer>adjust=pool.submit(()->{go.await();return postAdjustment("race-debit","-5").andReturn().getResponse().getStatus();});go.countDown();Set<Integer>statuses=Set.of(reserve.get(),adjust.get());assertTrue(statuses.contains(200));BigDecimalPair state=db.queryForObject("SELECT on_hand_quantity,reserved_quantity FROM inventory_balances",(r,n)->new BigDecimalPair(r.getBigDecimal(1),r.getBigDecimal(2)));assertTrue(state.reserved.compareTo(state.onHand)<=0);}finally{pool.shutdownNow();}}
 @Test void concurrentSerialReservationHasSingleWinner()throws Exception{grantReservations();grantTrace();db.update("UPDATE catalog_product_variants SET tracking_mode='SERIAL' WHERE id=?",V);UUID serial=UUID.randomUUID();db.update("INSERT INTO inventory_serials(id,tenant_id,variant_id,serial_number,normalized_serial_number,status,created_at,updated_at,version)VALUES (?,?,?,?,?,'ACTIVE',now(),now(),0)",serial,T,V,"RS-1","RS-1");postTrace("serial-stock","1",null,serial,L).andExpect(status().isOk());ExecutorService pool=Executors.newFixedThreadPool(8);try{List<Future<Integer>>calls=new ArrayList<>();for(int i=0;i<8;i++){int n=i;calls.add(pool.submit(()->postReservation("serial-hold-"+n,"1",null,serial,L).andReturn().getResponse().getStatus()));}int ok=0;for(var call:calls)if(call.get()==200)ok++;assertEquals(1,ok);assertEquals(1,db.queryForObject("SELECT reserved_quantity FROM inventory_balances",Integer.class));}finally{pool.shutdownNow();}}
 @Test void expiryAndReleaseRaceDecrementsProjectionOnce()throws Exception{grantReservations();postAdjustment("expiry-stock","1").andExpect(status().isOk());postReservation("expiry-hold","1",null,null,L).andExpect(status().isOk());UUID id=db.queryForObject("SELECT id FROM inventory_reservations WHERE idempotency_key='expiry-hold'",UUID.class);db.update("UPDATE inventory_reservations SET expires_at=now()-interval '1 minute' WHERE id=?",id);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> expiry=pool.submit(()->reservationService.expire());Future<Integer>release=pool.submit(()->{try{return mvc.perform(post("/api/v1/inventory/reservations/"+id+"/release").with(token())).andReturn().getResponse().getStatus();}catch(Exception e){throw new RuntimeException(e);}});expiry.get();assertEquals(200,release.get());assertEquals(0,db.queryForObject("SELECT reserved_quantity FROM inventory_balances",Integer.class));assertTrue(Set.of("EXPIRED","RELEASED").contains(db.queryForObject("SELECT status FROM inventory_reservations WHERE id=?",String.class,id)));}finally{pool.shutdownNow();}}
 private record BigDecimalPair(java.math.BigDecimal onHand,java.math.BigDecimal reserved){}private void grantReservations(){UUID role=db.queryForObject("SELECT id FROM roles WHERE tenant_id=?",UUID.class,T);for(String p:List.of("inventory-reservation:read","inventory-reservation:manage"))db.update("INSERT INTO role_permissions VALUES (?,?,?) ON CONFLICT DO NOTHING",T,role,p);}private ResultActions postReservation(String key,String quantity,UUID lot,UUID serial,UUID location)throws Exception{return mvc.perform(post("/api/v1/inventory/reservations").with(token()).header("Idempotency-Key",key).contentType("application/json").content("{\"referenceType\":\"MANUAL_HOLD\",\"referenceId\":\"REF-"+key+"\",\"variantId\":\""+V+"\",\"warehouseId\":\""+W+"\",\"locationId\":\""+location+"\",\"lotId\":"+(lot==null?"null":"\""+lot+"\"")+",\"serialId\":"+(serial==null?"null":"\""+serial+"\"")+",\"quantity\":\""+quantity+"\"}"));}private void grantTrace(){UUID role=db.queryForObject("SELECT id FROM roles WHERE tenant_id=?",UUID.class,T);for(String p:List.of("inventory-traceability:read","inventory-traceability:manage"))db.update("INSERT INTO role_permissions VALUES (?,?,?) ON CONFLICT DO NOTHING",T,role,p);}private ResultActions postTrace(String key,String delta,UUID lot,UUID serial,UUID location)throws Exception{return mvc.perform(post("/api/v1/inventory/adjustments").with(token()).header("Idempotency-Key",key).contentType("application/json").content(traceBody(delta,lot,serial,location)));}private String traceBody(String delta,UUID lot,UUID serial,UUID location){return "{\"variantId\":\""+V+"\",\"warehouseId\":\""+W+"\",\"locationId\":\""+location+"\",\"lotId\":"+(lot==null?"null":"\""+lot+"\"")+",\"serialId\":"+(serial==null?"null":"\""+serial+"\"")+",\"quantityDelta\":\""+delta+"\",\"reason\":\"MANUAL_CORRECTION\"}";}private ResultActions postAdjustment(String key,String delta)throws Exception{return mvc.perform(post("/api/v1/inventory/adjustments").with(token()).header("Idempotency-Key",key).contentType("application/json").content(body(delta)));}private String body(String delta){return "{\"variantId\":\""+V+"\",\"warehouseId\":\""+W+"\",\"locationId\":\""+L+"\",\"quantityDelta\":\""+delta+"\",\"reason\":\"MANUAL_CORRECTION\"}";}private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("admin").claim("tenant_id",T.toString()));}
